  `status` enum('DRAFT','COMPLETED','CANCELLED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT 'Trạng thái phiếu nhập kho thực tế',
  `has_rejected_items` tinyint(1) NOT NULL DEFAULT '0',
